          "description": "Dog breed thumbnail",
          "fit": "cover",
          "variant": "smallFeature"
        },
        {
          "id": "generatorCard",
          "component": "Card",
          "child": "generatorCol"
        },
        {
          "id": "generatorCol",
          "component": "Column",
          "children": [
            "genTitle",
            "genDesc",
            "nameField",
            "legsField",
            "skillsPicker",
            "generateBtn",
            "dividerLine",
            "resultSectionTitle",
            "resultText"
          ]
        },
        {
          "id": "genTitle",
          "component": "Text",
          "text": "Fictional Dog Generator",
          "variant": "body"
        },
        {
          "id": "genDesc",
          "component": "Text",
          "text": "Mix and match traits to create a brand-new fictional dog breed with distinct physical abilities.",
          "variant": "caption"
        },
