          "id": "nameField",
          "component": "TextField",
          "label": "Dog Breed Name",
          "value": {
            "path": "/generator/name"
          },
          "placeholder": "Enter breed name",
          "variant": "shortText"
        },
        {
          "id": "legsField",
          "component": "TextField",
          "label": "Number of Legs",
          "value": {
            "path": "/generator/legs"
          },
          "placeholder": "4",
          "variant": "number"
        },
        {
          "id": "skillsPicker",
          "component": "ChoicePicker",
          "label": "Skills",
          "variant": "multipleSelection",
          "options": [
            {
              "label": "Super Speed",
              "value": "speed"
            },
            {
              "label": "Laser Vision",
              "value": "laser"
            },
            {
              "label": "Invisibility",
              "value": "invisible"
            },
            {
              "label": "Flight",
              "value": "flight"
            }
          ],
          "value": {
            "path": "/generator/skills"
          },
          "displayStyle": "chips"
        },
        {
          "id": "generateBtnText",
          "component": "Text",
          "text": "Generate",
          "variant": "body"
        },
        {
          "id": "generateBtn",
          "component": "Button",
          "child": "generateBtnText",
          "variant": "primary",
          "action": {
            "event": {
              "name": "generate_dog",
              "context": {
                "name": {
                  "path": "/generator/name"
                },
                "legs": {
                  "path": "/generator/legs"
                },
                "skills": {
                  "path": "/generator/skills"
                }
              }
            }
          }
        },
        {
          "id": "dividerLine",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "resultSectionTitle",
          "component": "Text",
          "text": "Generated Breed Profile",
          "variant": "body"
        },
        {
          "id": "resultText",
          "component": "Text",
          "text": {
            "call": "formatString",
            "args": {
              "value": "The newly discovered '${/generator/name}' has ${/generator/legs} legs and incredible skills!"
            }
          },
          "variant": "body"
        }
      ],
      "dataModel": {
        "breeds": [
          {
            "url": "https://images.unsplash.com/photo-1543466835-00a7907e9de1"
          },
          {
            "url": "https://images.unsplash.com/photo-1583511655857-d19b40a7a54e"
          },
          {
            "url": "https://images.unsplash.com/photo-1537151608828-ea2b117b6f86"
          }
        ],
        "generator": {
          "name": "Galactic Rover",
          "legs": "4",
          "skills": [
            "speed"
          ]
        }
      }
    }
  }
]

